  "Sólo tú ves esto. Bot: juego automático con números normales. Todo: bot, daño ×40, botín, tickets y monedas por segundo. Con bot o ventajas no se sube al ranking.": "只有你看得到這一區。Bot：AI 自動玩，數值正常。Todo：AI、×40 傷害、掉落加成、每秒扭蛋券與金幣。有 AI 或加成的對局不計入排行榜。",
  "Bot": "AI",
