  "Has completado la Pokédex de {x}: en su banner, los shiny salen el doble (2 %). Lo tienes en la Mochila.": "你已集齊{x}圖鑑：在其卡池中，異色出現率翻倍（2%）。可在背包中查看。",
  "You completed the {x} Pokédex: in its banner, shinies are twice as likely (2%). You can find it in your Bag.": "你已集齊{x}圖鑑：在其卡池中，異色出現率翻倍（2%）。可在背包中查看。",
  "¡Amuleto Iris de {x}! Shiny al 2 % en su banner": "獲得{x}閃耀護符！該卡池異色率 2%",
  "{x} Shiny Charm! 2% shiny in its banner": "獲得{x}閃耀護符！該卡池異色率 2%",
  "Amuletos Iris: {x}": "閃耀護符：{x}",
  "Shiny Charms: {x}": "閃耀護符：{x}",
  "Pull ×100 ·": "抽 100 次 ·",
  "TIRADA ×100": "百連抽",
  "PULL ×100": "百連抽",
  "Saltar": "跳過",
  "Skip": "跳過",
  "Nuevos: {x}": "新獲得：{x}",
  "New: {x}": "新獲得：{x}",
  "Shiny: {x}": "異色：{x}",
  "Esferas de Mundo Misterioso, Amuletos Iris y gacha ×100": "不可思議迷宮寶玉、閃耀護符與百連抽",
  "Gacha: nueva tirada ×100, con 100 tickets normales o con 10 tickets ×10 (son diez ×10 seguidas, cada una con su Épica asegurada). La tragaperras gira 10 veces enseñando lo mejor de cada ×10 y al final ves un resumen (nuevos, shiny y Pokémonedas) con las cartas de mejor a peor. Para que quepa, ya no está la tirada ×1: se tira de 10 en 10 o de 100 en 100.": "扭蛋：新增百連抽，可用 100 張普通券或 10 張十連券（連續十次十連抽，每次都保底一個史詩）。老虎機會轉 10 次，展示每次十連中最好的結果，最後顯示匯總（新獲得、異色和寶可幣），卡牌按從好到差排列。為了騰出位置，取消了單抽：現在每次抽 10 次或 100 次。",
  "Gacha: botón Saltar (o Esc) durante la animación: se acaba la tragaperras y salen todas las cartas de golpe.": "扭蛋：動畫播放時可按「跳過」（或 Esc）：老虎機立即結束，所有卡牌一次顯示。",
  "Soporesfera": "睡眠寶玉",
  "Slumber Orb": "睡眠寶玉",
  "Ralentosfera": "緩慢寶玉",
  "Slow Orb": "緩慢寶玉",
  "Rafagaesfera": "吹飛寶玉",
  "Blowback Orb": "吹飛寶玉",
  "Focosfera": "聚氣寶玉",
  "Focus Orb": "聚氣寶玉",
  "Luminosfera": "光亮寶玉",
  "Luminous Orb": "光亮寶玉",
  "Rapidosfera": "加速寶玉",
  "Quick Orb": "加速寶玉",
  "Duerme a los enemigos de la pantalla 4 s (a los jefes, 1 s).": "讓螢幕內的敵人睡眠 4 秒（首領 1 秒）。",
  "Puts the enemies on screen to sleep for 4 s (bosses, 1 s).": "讓螢幕內的敵人睡眠 4 秒（首領 1 秒）。",
  "Los enemigos de la pantalla van un 50 % más lentos durante 8 s (los jefes, un 20 %).": "螢幕內的敵人移動速度降低 50%，持續 8 秒（首領 20%）。",
  "Enemies on screen move 50% slower for 8 s (bosses, 20%).": "螢幕內的敵人移動速度降低 50%，持續 8 秒（首領 20%）。",
  "Lanza lejos a los enemigos que tienes cerca (a los jefes, la mitad).": "把附近的敵人吹飛（首領只吹飛一半距離）。",
  "Blows nearby enemies far away (bosses, half as far).": "把附近的敵人吹飛（首領只吹飛一半距離）。",
  "+25 % de crítico durante 15 s, para ti y los compañeros cercanos.": "15 秒內會心率 +25%，對你和附近的隊友生效。",
  "+25% critical chance for 15 s, for you and nearby teammates.": "15 秒內會心率 +25%，對你和附近的隊友生效。",
  "Ves más campo (la cámara se aleja) durante 15 s, tú y los compañeros cercanos.": "15 秒內視野變大（鏡頭拉遠），對你和附近的隊友生效。",
  "You see more of the map (the camera zooms out) for 15 s, you and nearby teammates.": "15 秒內視野變大（鏡頭拉遠），對你和附近的隊友生效。",
  "+40 % de velocidad durante 10 s, para ti y los compañeros cercanos.": "10 秒內速度 +40%，對你和附近的隊友生效。",
  "+40% speed for 10 s, for you and nearby teammates.": "10 秒內速度 +40%，對你和附近的隊友生效。",
  "Esferas de Mundo Misterioso: objetos de un solo uso que se encuentran durante la partida (cofres, jefes y, a veces, al derrotar a un Pokémon). Soporesfera, Ralentosfera y Rafagaesfera duermen, frenan o lanzan lejos a los enemigos; Focosfera, Luminosfera y Rapidosfera te dan crítico, más campo de visión o velocidad a ti y a los compañeros cercanos. Llevas hasta 4 distintas (3 de cada) y se usan con las teclas 5-8, tocando su casilla encima de los ataques o con X / Y en el mando. A los jefes y legendarios les afectan menos.": "不可思議迷宮的寶玉：在對局中獲得的一次性道具（寶箱、首領，打倒寶可夢時也有機會掉落）。睡眠寶玉、緩慢寶玉和吹飛寶玉能讓敵人睡眠、減速或被吹飛；聚氣寶玉、光亮寶玉和加速寶玉能為你和附近的隊友提升會心率、擴大視野或提高速度。最多攜帶 4 種（每種 3 個），用 5-8 鍵、點擊招式上方的格子或手把的 X / Y 使用。對首領和傳說寶可夢的效果較弱。",
  "X para usarla": "按 X 使用",
  "X to use it": "按 X 使用",
  "tócala encima de tus ataques": "點擊招式上方的格子",
  "tap it above your moves": "點擊招式上方的格子",
  "tecla {x}": "按鍵 {x}",
  "key {x}": "按鍵 {x}",
  "Tus esferas": "你的寶玉",
  "Your orbs": "你的寶玉",
  "esferas ·": "寶玉 ·",
  "orbs ·": "寶玉 ·",
  "Arrastra el dedo para moverte · toca un ataque para cambiarlo · toca una esfera para usarla": "拖動手指移動 · 點擊招式切換 · 點擊寶玉使用",
  "Drag your finger to move · tap a move to switch · tap an orb to use it": "拖動手指移動 · 點擊招式切換 · 點擊寶玉使用",
  "Aún no llevas esferas. Salen de los cofres, de los jefes y, a veces, al derrotar a un Pokémon.": "你還沒有寶玉。寶箱、首領會掉落，打倒寶可夢時也有機會獲得。",
  "You have no orbs yet. They come from chests, bosses and sometimes from defeated Pokémon.": "你還沒有寶玉。寶箱、首領會掉落，打倒寶可夢時也有機會獲得。",
  "Movimientos evolucionados con su nombre": "進化招式保留原名",
  "Los movimientos evolucionados ya no cambian de nombre: se llaman igual con un «+» (Puño Meteoro pasa a Puño Meteoro +). Hacen lo mismo que antes y se siguen distinguiendo por el borde dorado.": "進化後的招式不再改名：保留原名並加上「+」（彗星拳變為彗星拳 +）。效果與之前相同，仍以金色邊框區分。",
  "EN DIRECTO": "直播中",
  "LIVE": "直播中",
  "Mi canal de YouTube": "我的 YouTube 頻道",
  "My YouTube channel": "我的 YouTube 頻道",
  "¡Estoy en directo! Pulsa para verlo": "我正在直播！點擊觀看",
  "I'm live! Click to watch": "我正在直播！點擊觀看",
  "Botón de YouTube arriba, junto a Novedades: lleva al canal del juego y, cuando hay directo, se pone rojo con «EN DIRECTO» y te lleva a verlo.": "頂部「更新消息」旁新增 YouTube 按鈕：可前往遊戲頻道；直播時會變紅並顯示「直播中」，點擊即可觀看。",
  "En la Sentencia de Arceus, el veneno y las quemaduras quitan poco y siempre lo mismo a los legendarios (antes el veneno quitaba un % de su vida): envenenar y huir ya no sirve, hay que pegarles.": "在阿爾宙斯的審判中，中毒和灼傷對傳說寶可夢只造成少量的固定傷害（以前中毒會扣除其一定百分比的HP）：下毒後逃跑不再有效，必須正面攻擊。",
  "Puño Meteoro pega menos: 24 de daño en vez de 34 y una zona un poco más pequeña. Al máximo y evolucionado hacía casi el doble que Avalancha; ahora están a la par.": "彗星拳傷害降低：從 34 降至 24，範圍也略微縮小。滿級並進化後，它的傷害幾乎是岩崩的兩倍；現在兩者持平。",
