  "¡Arceus lleva la {x}! Ahora es de tipo {x}": "阿爾宙斯帶著{x}！現在是{x}屬性",
  "Arceus holds the {x}! It is now {x} type": "阿爾宙斯帶著{x}！現在是{x}屬性",
  "¡Arceus va a romper vuestros objetos!": "阿爾宙斯要擊碎你們的道具了！",
  "Arceus is about to break your items!": "阿爾宙斯要擊碎你們的道具了！",
  "¡Objeto roto: {x}!": "道具被擊碎：{x}！",
  "Item broken: {x}!": "道具被擊碎：{x}！",
  "Es invencible: aguanta y hazle todo el daño que puedas": "它無法被打倒：堅持下去，盡可能對它造成傷害",
  "It is invincible: survive and deal as much damage to it as you can": "它無法被打倒：堅持下去，盡可能對它造成傷害",
  "DAÑO A ARCEUS · {x}": "對阿爾宙斯的傷害 · {x}",
  "DAMAGE TO ARCEUS · {x}": "對阿爾宙斯的傷害 · {x}",
  "Daño a Arceus": "對阿爾宙斯的傷害",
  "Damage to Arceus": "對阿爾宙斯的傷害",
  "Tiempo aguantado": "堅持時間",
  "Time survived": "堅持時間",
  "El daño a Arceus no tiene ranking por Pokémon.": "對阿爾宙斯的傷害沒有按寶可夢的排行。",
  "Damage to Arceus has no per-Pokémon ranking.": "對阿爾宙斯的傷害沒有按寶可夢的排行。",
  "Todavía nadie le ha hecho daño a Arceus aquí. ¡Llega al minuto 30 y pégale!": "這裡還沒有人對阿爾宙斯造成傷害。撐到第 30 分鐘去打牠吧！",
  "Nobody has damaged Arceus here yet. Reach minute 30 and hit it!": "這裡還沒有人對阿爾宙斯造成傷害。撐到第 30 分鐘去打牠吧！",
  "Aún no estás en el top 50 de daño.": "你還沒有進入傷害前 50 名。",
  "You're not in the damage top 50 yet.": "你還沒有進入傷害前 50 名。",
  "Tu puesto: {x}": "你的名次：{x}",
  "Your rank: {x}": "你的名次：{x}",
  "Ranking de daño a Arceus y Tablas": "阿爾宙斯傷害排行與石板",
  "Arceus damage ranking and Plates": "阿爾宙斯傷害排行與石板",
  "Ranking partido en dos: a la izquierda, el daño que le has hecho a Arceus; a la derecha, el tiempo aguantado, como siempre. Las dos mitades se cargan a la vez. Todas las tablas empiezan de cero.": "排行榜分成兩半：左邊是你對阿爾宙斯造成的傷害，右邊照舊是堅持時間。兩邊同時載入。所有排行榜從零開始。",
  "Sentencia de Arceus: ahora se le puede pegar. Es invencible y sólo recibe una pequeña parte del daño (cada vez menos), y los ataques le apuntan cuando no queda ningún legendario.": "阿爾宙斯的審判：現在可以攻擊牠了。牠無法被打倒，只會受到一小部分傷害（越來越少），沒有傳說寶可夢時攻擊會瞄準牠。",
  "Tablas: en cada partida Arceus lleva una al azar, que le da su tipo (se avisa al entrar en la arena). Ya no hay un tipo de ataque que sea siempre el mejor.": "石板：每局阿爾宙斯會隨機帶著一塊，並變成它的屬性（進入競技場時會提示）。不再有永遠最強的招式屬性。",
  "En el minuto 35, Arceus rompe el objeto de todos (Banda Focus incluida).": "第 35 分鐘時，阿爾宙斯會擊碎所有人的道具（包括氣勢披帶）。",
  "Los legendarios de la Sentencia ya no son el doble de fuertes que el anterior: cada uno tiene un 25 % más de vida y un 15 % más de daño, así que se pueden tumbar. Ya no hay límite de 45 minutos en el ranking.": "審判中的傳說寶可夢不再比上一隻強一倍：每隻多 25% 體力和 15% 傷害，可以被打倒了。排行榜不再有 45 分鐘的上限。",
  "Ataques en la colección y ventanas del menú": "收藏中的招式與選單視窗",
  "Colección: los iconos de los ataques que puede aprender cada Pokémon son el doble de grandes y, al pasar el ratón (o al tocarlos en el móvil), dicen su tipo, si es físico o especial y lo que hace.": "收藏：每隻寶可夢可學會的招式圖示放大了一倍，滑鼠懸停（或在手機上點擊）時會顯示其屬性、物理或特殊類別以及效果。",
  "Las ventanas del menú, Ajustes, Novedades y Apoyar se pueden cerrar pulsando fuera de ellas, además de con Volver o Cerrar.": "選單中的視窗、設定、更新消息和支持現在可以點擊外部關閉，不只是用返回或關閉按鈕。",
  "Las ventanas de la Tienda Kecleon y de Novedades ya no se meten por debajo de la barra de arriba: ahora empiezan debajo de ella, como las demás.": "隱形龍商店和更新消息的視窗不再被頂部列遮住：現在和其他視窗一樣從頂部列下方開始。",
