  "Halloween Candy": "萬聖節糖果",
  "Lo sueltan los Pokémon Fantasma y las calabazas en Halloween. Con ellos se compran las skins de bruja en la Tienda Kecleon.": "萬聖節期間由幽靈屬性寶可夢和南瓜掉落，可在隱形龍商店兌換女巫裝扮。",
  "Dropped by Ghost-type Pokémon and pumpkins during Halloween. Use them to buy witch skins at the Kecleon Shop.": "萬聖節期間由幽靈屬性寶可夢和南瓜掉落，可在隱形龍商店兌換女巫裝扮。",
