  "You don't have enough candy.": "糖果不足。",
  "¡Feliz Halloween! Póntela en la ficha del Pokémon.": "萬聖節快樂！在寶可夢詳情中穿上吧。",
  "Happy Halloween! Put it on from the Pokémon’s page.": "萬聖節快樂！在寶可夢詳情中穿上吧。",
  "Halloween: skins de bruja": "萬聖節：女巫裝扮",
  "Halloween: witch skins": "萬聖節：女巫裝扮",
  "Sólo hasta el 1 de noviembre. Los caramelos salen en las partidas (sobre todo de los Fantasma y las calabazas) y ante el gran Gengar. La skin es para siempre; se pone y se quita en la ficha del Pokémon.": "僅限 11 月 1 日前。糖果在對局中掉落（主要來自幽靈屬性寶可夢和南瓜），面對大耿鬼時也會獲得。裝扮永久擁有，可在寶可夢詳情中穿上或脫下。",
  "Only until November 1. Candy drops during runs (mostly from Ghost types and pumpkins) and when you face the great Gengar. Skins are yours forever; put them on or take them off from the Pokémon’s page.": "僅限 11 月 1 日前。糖果在對局中掉落（主要來自幽靈屬性寶可夢和南瓜），面對大耿鬼時也會獲得。裝扮永久擁有，可在寶可夢詳情中穿上或脫下。",
  "Tienes {x} caramelos": "你有 {x} 個糖果",
  "You have {x} candy": "你有 {x} 個糖果",
  "Sombrero y capa de bruja para {x}.": "{x}的女巫帽和斗篷。",
  "Witch hat and cape for {x}.": "{x}的女巫帽和斗篷。",
  "Comprada. Póntela o quítatela en la ficha del Pokémon.": "已購買。可在寶可夢詳情中穿上或脫下。",
  "Bought. Put it on or take it off from the Pokémon’s page.": "已購買。可在寶可夢詳情中穿上或脫下。",
  "Comprada. Se pone cuando tengas a {x}.": "已購買。獲得{x}後即可穿上。",
  "Bought. You can wear it once you have {x}.": "已購買。獲得{x}後即可穿上。",
