  "Sus movimientos Normal y Lucha dañan del todo a los Fantasma.": "一般和格鬥屬性招式能完全擊中幽靈屬性。",
  "Its Normal and Fighting moves fully hit Ghost types.": "一般和格鬥屬性招式能完全擊中幽靈屬性。",
  "+30 % de daño Roca, Tierra y Acero con tormenta de arena.": "沙暴時岩石、地面和鋼屬性傷害+30%。",
  "+30% Rock, Ground and Steel damage in a sandstorm.": "沙暴時岩石、地面和鋼屬性傷害+30%。",
  "+40 % de daño especial con sol, pero el sol le quita algo de vida.": "晴天時特殊傷害+40%，但會被晴天消耗一些體力。",
  "+40% special damage in sun, but the sun drains some HP.": "晴天時特殊傷害+40%，但會被晴天消耗一些體力。",
  "Sus golpes críticos hacen ×2 de daño (en vez de ×1,5).": "擊中要害時傷害×2（而不是×1.5）。",
  "Its critical hits deal ×2 damage (instead of ×1.5).": "擊中要害時傷害×2（而不是×1.5）。",
