  "Its boosting moves recharge 30% faster.": "強化類招式冷卻時間−30%。",
  "Sin objeto va un 15 % más rápido.": "沒有攜帶道具時速度+15%。",
  "Without an item it is 15% faster.": "沒有攜帶道具時速度+15%。",
  "No se deja impresionar: recibe un 8 % menos de daño.": "不為所動：受到的傷害-8%。",
