  "Si le frenan, se pica: +20 % de daño físico mientras dure.": "被減速時會反擊：期間物理傷害+20%。",
  "If it is slowed it fights back: +20% physical damage while it lasts.": "被減速時會反擊：期間物理傷害+20%。",
  "Si le frenan, se pica: +20 % de daño especial mientras dure.": "被減速時會反擊：期間特殊傷害+20%。",
  "If it is slowed it fights back: +20% special damage while it lasts.": "被減速時會反擊：期間特殊傷害+20%。",
