  "Takes 10% less special damage.": "受到的特殊傷害-10%。",
  "Recibe un 8 % menos de daño físico.": "受到的物理傷害-8%。",
  "Takes 8% less physical damage.": "受到的物理傷害-8%。",
  "La lava no le quema y recibe la mitad de daño de Fuego.": "熔岩不會燙傷牠，受到的火屬性傷害減半。",
