  "Cada día hay otras 8. Una MT enseña su ataque a un Pokémon que lo aprenda en los juegos, para siempre (se gasta al usarla).": "每天會換8種。招式學習器能讓在正作中可以學會該招式的寶可夢永久學會牠（用後消失）。",
  "There are 8 new ones every day. A TM teaches its move forever to a Pokémon that learns it in the games (it is used up).": "每天會換8種。招式學習器能讓在正作中可以學會該招式的寶可夢永久學會牠（用後消失）。",
