  "Para usarlo, abre la colección, elige un Pokémon y pulsa Menta, Cápsula o Enseñar MT en su ficha.": "使用方法：打開收藏，選擇一隻寶可夢，在牠的頁面裡點「薄荷」「膠囊」或「教招式學習器」。",
  "To use it, open your collection, pick a Pokémon and press Mint, Capsule or Teach TM on its page.": "使用方法：打開收藏，選擇一隻寶可夢，在牠的頁面裡點「薄荷」「膠囊」或「教招式學習器」。",
