  "¡Irascible!": "憤怒穴位！",
  "Anger Point!": "憤怒穴位！",
  "Mejora nueva: Tienda Kecleon (botón en el menú) con Mentas, Cápsulas Habilidad y 8 MT nuevas cada día. Cada Pokémon tiene ahora su naturaleza (±10 % a dos stats) y su habilidad, con efecto en la partida; se ven y se cambian en su ficha de la colección. Las MT enseñan para siempre ataques de fuera de sus tipos, pero sólo si los aprende en los juegos (Mewtwo puede aprender Bola Sombra; Psyduck no puede aprender Lanzallamas). Gracias a TheAdro7 por la idea y el trabajo de base.": "新內容：隱形龍商店（選單中的按鈕），出售薄荷、特性膠囊和每天8種新的招式學習器。現在每隻寶可夢都有自己的性格（兩項能力±10%）和特性，在對局中會生效；可以在收藏中牠的頁面查看和更改。招式學習器能讓寶可夢永久學會本身屬性以外的招式，但只限牠在正作中能學會的（超夢能學會暗影球，可達鴨學不會噴射火焰）。感謝 TheAdro7 提供創意和基礎工作。",
  "New: the Kecleon Shop (button in the menu) with Mints, Ability Capsules and 8 new TMs every day. Every Pokémon now has its own nature (±10% to two stats) and ability, with an effect in the run; you can see and change them on its page in the collection. TMs permanently teach moves outside its types, but only if it learns them in the games (Mewtwo can learn Shadow Ball; Psyduck cannot learn Flamethrower). Thanks to TheAdro7 for the idea and the groundwork.": "新內容：隱形龍商店（選單中的按鈕），出售薄荷、特性膠囊和每天8種新的招式學習器。現在每隻寶可夢都有自己的性格（兩項能力±10%）和特性，在對局中會生效；可以在收藏中牠的頁面查看和更改。招式學習器能讓寶可夢永久學會本身屬性以外的招式，但只限牠在正作中能學會的（超夢能學會暗影球，可達鴨學不會噴射火焰）。感謝 TheAdro7 提供創意和基礎工作。",
  "¡Bienvenido a la Tienda Kecleon!": "歡迎光臨隱形龍商店！",
  "Welcome to the Kecleon Shop!": "歡迎光臨隱形龍商店！",
