  "cambiar": "切換",
  "switch": "切換",
  "Cooperativo: si caes, puedes mirar a un compañero que siga en pie mientras esperas a que te levanten. Pulsa el botón que sale debajo del aviso (o Q / E, o LB / RB en el mando) para pasar de uno a otro y volver a ti. Sólo cambia la cámara: no gasta más conexión.": "合作模式：倒下後，在等待隊友救起時可以觀看仍在戰鬥的隊友。按提示下方的按鈕（或 Q / E，控制器上為 LB / RB）在隊友之間切換並回到自己。只切換鏡頭，不會額外消耗網路。",
  // ---- añadido por tools/zh_patch_fill.js (traducción oficial de upstream) ----
  "¡Los Pokémon salvajes se vuelven cada vez más fuertes!": "野生寶可夢越來越強了！",
