  "×1,8 daño, rayo un 50% más grueso y carga más rápido": "傷害 ×1.8，光束寬度 +50%，蓄力更快",
  "×1.8 damage, 50% thicker beam and faster charge": "傷害 ×1.8，光束寬度 +50%，蓄力更快",
  "×1,8 daño, +1 vuelta y más radio": "傷害 ×1.8、旋轉圈數 +1，半徑增大",
