  "Xbox, PlayStation, Switch and most USB or Bluetooth controllers. Connect it and press any button.": "支援 Xbox、PlayStation、Switch 及大多數 USB／藍牙手把。接上後按任意鍵即可。",
  "Move, switch attacks and use the menus with a controller.": "用手把移動、切換招式並操作選單。",
  "The controller vibrates when you take damage (if your controller and browser support it).": "受到傷害時手把會震動（需手把與瀏覽器支援）。",
