  "special moves": "特殊招式",
  "physical moves": "物理招式",
  "With {x} it deals {x} %: it hits harder with special moves.": "{x} 使用只有 {x}% 威力：牠比較擅長特殊招式。",
  "With {x} it deals {x} %: it hits harder with physical moves.": "{x} 使用只有 {x}% 威力：牠比較擅長物理招式。",
  "Your moves": "你的招式",
  "Damage": "傷害",
  "Per second": "每秒",
