  "Put the attacks, the pause button and the joystick (fixed, if you like) anywhere on the screen.": "把招式、暫停與搖桿（可選固定）放到畫面上任何位置。",
  "Arrastra los botones a donde quieras": "把按鈕拖到想要的位置",
