  "Anchored: it appears where you put your finger and stays there until you lift it.": "錨定：出現在手指按下的位置，放開前都固定在那裡。",
  "Flotante: aparece donde pones el dedo. Fijo: siempre en el mismo sitio.": "浮動：手指按在哪就出現在哪。固定：永遠在同一位置。",
