  "La única web oficial de PokéSurvivor es pokesurvivor.com. El juego es y será gratis: si alguien te pide pagar, no somos nosotros.": "PokéSurvivor 唯一的官方網站是 pokesurvivor.com。遊戲永遠免費：如果有人要你付錢，那不是我們。",
  "The only official PokéSurvivor website is pokesurvivor.com. The game is and always will be free: if anyone asks you to pay, it isn't us.": "PokéSurvivor 唯一的官方網站是 pokesurvivor.com。遊戲永遠免費：如果有人要你付錢，那不是我們。",
  "Important: save your game": "重要：記得存檔",
