  "Xbox, PlayStation, Switch y la mayoría de mandos USB o Bluetooth. Conéctalo y pulsa cualquier botón.": "支援 Xbox、PlayStation、Switch 及大多數 USB／藍牙手把。接上後按任意鍵即可。",
  "Moverte, cambiar de ataque y manejar los menús con el mando.": "用手把移動、切換招式並操作選單。",
  "El mando vibra al recibir daño (si el mando y el navegador lo permiten).": "受到傷害時手把會震動（需手把與瀏覽器支援）。",
