  "desplazar las listas · apuntar (si activas Apuntar a mano en Accesibilidad)": "捲動清單・瞄準（在「無障礙」開啟手動瞄準時）",
  "Accesibilidad": "無障礙",
  "Apuntado": "瞄準",
  "Apuntar a mano": "手動瞄準",
  "Tus ataques van hacia el ratón (o hacia donde empujes el stick derecho del mando) en vez de al enemigo más cercano. Si sueltas el stick y no mueves el ratón, vuelve a apuntar solo. La cadena y los meteoros siguen buscando a los enemigos solos.": "招式改朝滑鼠（或手把右搖桿推的方向）發射，而不是最近的敵人。放開搖桿且不動滑鼠時，會恢復自動瞄準。連鎖與流星類招式仍會自動追蹤敵人。",
