  "Como invitado la partida no se guarda.": "訪客模式不會儲存進度。",
  "Ya está todo guardado en la nube.": "全部都已經存到雲端了。",
  "Sin conexión: se guardará en cuanto vuelva.": "目前離線：恢復連線後會自動存檔。",
  "No se pudo guardar. Vuelve a probar en un momento.": "存檔失敗，請稍後再試。",
