  "Pulsa «Listo» (o la tecla R) cuando estés preparado.": "準備好了就按「準備」（或按 R 鍵）。",
  "Listo. Cuando el anfitrión empiece, entraréis todos a la vez.": "已準備。房主開始後，所有人會同時進入遊戲。",
  "Esperando a que estén listos: {x}.": "等待準備完成：{x}。",
  "Esperando a que {x} vuelva a la sala.": "等待 {x} 回到房間。",
  "Saltar la animación (resultado directo)": "跳過動畫（直接顯示結果）",
  "Minimapa": "小地圖",
  "Radar en la esquina: jefes, legendarios, grieta, cofres grandes, shinies y compañeros.": "右上角的雷達：顯示頭目、傳說、裂縫、大寶箱、閃光與隊友的位置。",
  "¡Has recibido un regalo!": "你收到禮物了！",
  "¡Has recibido {x} regalos!": "你收到 {x} 份禮物！",
  "De": "來自",
  "¡Gracias!": "收下！",
  "Pokémonedas": "寶可幣",
  "Todo al máximo": "一鍵升滿",
  "Volver a cero": "回到初始",
  "¿Poner a cero todas las mejoras de": "要把這隻的所有強化歸零嗎：",
  "{x}: todas las mejoras al máximo": "{x}：所有強化已升滿",
  "{x}: mejoras a cero": "{x}：強化已歸零",
  "¿Regalar": "要送",
  "a": "給",
  "Regalar": "送出",
  "Regalar monedas a": "送金幣給",
  "Cantidad": "數量",
  "Enviar": "送出",
  "Mis ventajas": "我的特權",
  "Encendidas": "開啟",
  "Apagadas": "關閉",
  "AHORA: APAGADAS. La siguiente partida es como la original y cuenta para el ranking (en grupo, la de todo el equipo).": "目前：關閉。下一局是原版數值，並計入排行榜（組隊時整隊都計入）。",
  "AHORA: ENCENDIDAS. La siguiente partida tiene tus ventajas y no cuenta para el ranking.": "目前：開啟。下一局有你的特權，不計入排行榜。",
