  "PokéSurvivor es y será": "PokéSurvivor 現在與未來都會",
  "gratis": "免費",
  ", sin anuncios ni compras. Si quieres ayudar a que siga en línea, puedes hacer una": "，沒有廣告或內購。如果想協助維持服務，你可以",
