  "¿Te está gustando PokéSurvivor? Lo hago yo solo y los servidores cuestan dinero. Si quieres, puedes ayudarme a mantenerlo en línea.": "喜歡 PokéSurvivor 嗎？原作者獨力開發這款遊戲，伺服器需要費用。如果願意，你可以協助維持線上服務。",
