  "· Tickets are earned by playing: some Pokémon drop them when defeated, and bosses and rift legendaries sometimes give ×10 tickets.": "· 遊玩即可獲得抽獎券：部分寶可夢被擊敗時會掉落，頭目和裂縫中的傳說寶可夢有時會掉落十連抽獎券。",
